declare_args() {
  # May need to enable to fix recursion when vkAcquireNextImageKHR() returns
  # back to ANGLE from eglClientWaitSyncKHR(). May happen if Android
  # Presentation Engine uses EGL_KHR_fence_sync instead of
  # EGL_ANDROID_native_fence_sync for synchronization. To check call: adb shell
  # "dumpsys SurfaceFlinger | grep 'Sync configuration'" The Android's
  # "testDrawingHardwareBitmapNotLeaking" test may be used for testing. Disable
  # this option to save performance on platforms that does not require
  # recursion.
  angle_enable_context_mutex_recursion = angle_enable_global_mutex_recursion
}

if (angle_build_all) {
  group("all") {
    testonly = true
    deps = [
      ":angle",
      ":angle_shader_translator",
      ":noop_target",
      ":translator_fuzzer",
      ":xxhash_fuzzer",
      "$angle_root/samples:angle_samples",
      "$angle_root/src/tests:angle_tests",
    ]
    if (angle_enable_cl) {
      deps += [ "$angle_root/src/libOpenCL:angle_cl" ]
    }
    if (angle_enable_cl && angle_enable_vulkan) {
      # OpenCL through Vulkan in ANGLE requires clspv for online compiler
      deps += [ "$angle_clspv_dir:clspv" ]
    }
    if (angle_build_mesa) {
      deps += [ "$angle_root/third_party/mesa" ]
    }
    data_deps = [ "$angle_root/infra/orchestrator:orchestrator_all" ]
  }
}

if (build_angle_end2end_tests_library) {
  group("angle_end2end_tests_library") {
    testonly = true
    deps = [ "src/tests:angle_end2end_tests" ]
  }
}

